  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for WP-004: Orchestrator Runs flicker-free DOM patching and scroll preservation.
  5	 *
  6	 * Coverage areas:
  7	 *   1. _orchRunsStructureKey — pure key generation for run list structure
  8	 *   2. _patchOrchStatusCard — in-place status card update without rebuilding the runs list
  9	 *   3. renderRunsList (via renderProjectDetail) — scrollTop save/restore around innerHTML rebuild
 10	 *   4. pollQueue behaviour — in-place patch for data-only changes, structural rebuild otherwise
 11	 *   5. Log preview widgets survive data-only status card updates (no drain)
 12	 *   6. Kill/dismiss event handlers continue to work after in-place updates
 13	 */
 14	
 15	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
 16	import { readFileSync } from 'node:fs';
 17	import { join } from 'node:path';
 18	import vm from 'node:vm';
 19	
 20	// ---------------------------------------------------------------------------
 21	// Load client scripts
 22	// ---------------------------------------------------------------------------
 23	
 24	const publicDir = join(__dirname, '../../gui/public');
 25	const projectDetailJs = readFileSync(join(publicDir, 'views/project-detail.js'), 'utf-8');
 26	
 27	beforeAll(() => {
 28	  (globalThis as Record<string, unknown>)['marked'] = {
 29	    parse: (s: string) => '<p>' + s + '</p>',
 30	  };
 31	
 32	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
 33	    renderStatusCard:    vi.fn().mockReturnValue('<div class="orchestrator-status-card">card</div>'),
 34	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
 35	      const btn = document.createElement('button');
 36	      btn.className = 'kill-btn';
 37	      btn.textContent = 'Kill';
 38	      return btn;
 39	    }),
 40	    renderDismissButton: vi.fn(),
 41	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()),
 42	    renderProgressBadge: vi.fn().mockReturnValue(''),
 43	    renderCliReference:  vi.fn().mockReturnValue(''),
 44	  };
 45	
 46	  (globalThis as Record<string, unknown>)['Router'] = {
 47	    _setPolling:   vi.fn(),
 48	    _clearPolling: vi.fn(),
 49	  };
 50	
 51	  vm.runInThisContext(projectDetailJs);
 52	});
 53	
 54	beforeEach(() => {
 55	  vi.clearAllMocks();
 56	  globalThis.OrchestratorWidgets.renderStatusCard
 57	    .mockReturnValue('<div class="orchestrator-status-card">card</div>');
 58	  globalThis.OrchestratorWidgets.renderLogPreview.mockReturnValue(vi.fn());
 59	  globalThis.OrchestratorWidgets.renderKillButton
 60	    .mockImplementation((_id: string, _cb: () => void) => {
 61	      const btn = document.createElement('button');
 62	      btn.className = 'kill-btn';
 63	      btn.textContent = 'Kill';
 64	      return btn;
 65	    });
 66	});
 67	
 68	// ---------------------------------------------------------------------------
 69	// Global type declarations
 70	// ---------------------------------------------------------------------------
 71	
 72	declare global {
 73	  // eslint-disable-next-line no-var
 74	  var renderProjectDetail: (app: HTMLElement, repo: string, slug: string) => void;
 75	  // eslint-disable-next-line no-var
 76	  var _patchOrchStatusCard: (matchingQueueEntry: Record<string, unknown> | null) => void;
 77	  // eslint-disable-next-line no-var
 78	  var _orchRunsStructureKey: (
 79	    sorted: Array<{ filename?: string; is_active?: boolean }>,
 80	    activeFilename: string | null
 81	  ) => string;
 82	  // eslint-disable-next-line no-var
 83	  var API: Record<string, Mock>;
 84	  // eslint-disable-next-line no-var
 85	  var OrchestratorWidgets: {
 86	    renderStatusCard:    Mock;
 87	    renderKillButton:    Mock;
 88	    renderDismissButton: Mock;
 89	    renderLogPreview:    Mock;
 90	    renderProgressBadge: Mock;
 91	    renderCliReference:  Mock;
 92	  };
 93	  // eslint-disable-next-line no-var
 94	  var Router: {
 95	    _setPolling:   Mock;
 96	    _clearPolling: Mock;
 97	  };
 98	}
 99	
100	// ---------------------------------------------------------------------------

 1	/* ============================================================
 2	   views/project-detail.js — Project Detail view
 3	   Sections 4b–4d of the MCP Server Dashboard SPA
 4	   Depends on: API, Router, marked, escapeHtml, formatDate,
 5	               statusBadge, showLoading, showError,
 6	               OrchestratorWidgets (js/orchestrator-widgets.js),
 7	               UI (components.js)
 8	
 9	   DOM Contract (patch functions — see §4c-i):
10	   The following element IDs and data attributes are written by
11	   renderProjectDetail() and read by the _patch* helpers on every
12	   poll cycle.  Any change to these anchors must be coordinated
13	   between both sites:
14	
15	     #project-status-badge   — <span> wrapping the project status badge
16	                               in the page header (inner HTML is replaced
17	                               by _patchProjectStatus).
18	     #health-badge           — <span> for the project health badge
19	                               (textContent + className patched by
20	                               _patchHealthBadge).
21	     #synthesis-link-row     — <div> row containing the synthesis link;
22	                               always pre-rendered (display:none when not
23	                               ready) and toggled by _patchSynthesisLink.
24	     #timing-info            — Wrapper <span> for the three timing fields
25	                               below; _patchTimingInfo checks for its
26	                               presence before patching children.
27	       #timing-duration      — <span> showing elapsed project duration.
28	       #timing-active        — <span> showing total active pipeline time.
29	       #timing-runs          — <span> showing total pipeline-run count.
30	     tr[data-wp-id="WP-###"] — One <tr> per work package row; the
31	                               data-wp-id attribute is the stable lookup
32	                               key used by _patchWpRow.
33	       .wp-status-cell       — <td> inside the WP row holding the status
34	                               badge; replaced by _patchWpRow.
35	       .wp-pipeline-track-cell — <td> inside the WP row holding the
36	                               pipeline-track display; replaced by
37	                               _patchWpRow.
38	     #orch-status-card-container — <div> inside .orch-active-run-section
39	                               that wraps the OrchestratorWidgets status
40	                               card for the active run.  Its innerHTML is
41	                               replaced by _patchOrchStatusCard on every
42	                               data-only poll tick (WP-004).  The log
43	                               preview widget (#orch-project-log-preview)
44	                               is a sibling, not a child, so it survives
45	                               in-place status card updates intact.
46	   ============================================================ */
47	
48	// Module-scoped log-preview cleanup registry.
49	// Each renderProjectDetail() call drains this array before creating new widgets.
50	var _pdLogPreviewCleanups = [];
51	
52	/* ----------------------------------------------------------
53	   4b. View: Plan Document
54	   ---------------------------------------------------------- */
55	function extractSynopsis(markdown) {
56	  var match = markdown.match(/## Summary\s*\n([\s\S]*?)(?=\n## |\n---|\s*$)/);
57	  return match ? match[1].trim() : null;
58	}
59	
60	async function renderPlan(app, repo, slug) {
61	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
62	  try {
63	    var result = await API.getPlanDocument(repo, slug);
64	    var html = marked.parse(result.content);
65	    app.innerHTML =
66	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
67	      '<div class="plan-content">' + html + '</div>';
68	  } catch (err) {
69	    if (err && err.code === 'NOT_FOUND') {
70	      app.innerHTML =
71	        breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
72	        '<p class="empty-state">Plan document not available for this project.</p>';
73	    } else {
74	      app.innerHTML = UI.banner('error', 'Failed to load plan document.');
75	    }
76	  }
77	}
78	
79	/* ----------------------------------------------------------
80	   4b-ii. View: Synthesis Document
81	   ---------------------------------------------------------- */
82	async function renderSynthesis(app, repo, slug) {
83	  app.innerHTML = '<p class="loading">Loading synthesis\u2026</p>';
84	  try {
85	    var result = await API.getSynthesisDocument(repo, slug);
86	    var html = marked.parse(result.content);
87	    app.innerHTML =
88	      breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
89	      '<div class="synthesis-content">' + html + '</div>';
90	  } catch (err) {
91	    if (err && err.code === 'NOT_FOUND') {
92	      app.innerHTML =
93	        breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
94	        '<p class="empty-state">Synthesis document not available for this project.</p>';
95	    } else {
96	      app.innerHTML = UI.banner('error', 'Failed to load synthesis document.');
97	    }
98	  }
99	}

101	// Helpers
102	// ---------------------------------------------------------------------------
103	
104	function makeProject(overrides: Record<string, unknown> = {}) {
105	  return {
106	    meta: {
107	      status: 'IN_PROGRESS',
108	      title: 'Test Project',
109	      plan_path: '/some/path',
110	      date_created: '2026-01-01T00:00:00Z',
111	      last_updated: '2026-01-01T00:00:00Z',
112	      ...overrides,
113	    },
114	    work_packages: [],
115	    project_comments: [],
116	    project_name: 'Test Project',
117	    timing: null,
118	    server_version: null,
119	    ledger_version: null,
120	    synthesis_generated: false,
121	  };
122	}
123	
124	/**
125	 * Installs globalThis.API and renders the project detail page.
126	 * Returns once the orchestrator-runs-section is no longer showing the loading placeholder.
127	 */
128	async function renderWithAPI(
129	  app: HTMLElement,
130	  repo: string,
131	  slug: string,
132	  apiStubs: {
133	    getProject?: () => Promise<unknown>;
134	    getPlanDocument?: () => Promise<unknown>;
135	    getWorkPackageOverview?: () => Promise<unknown>;
136	    getProjectHealth?: () => Promise<unknown>;
137	    getRunLogs?: () => Promise<unknown>;
138	    orchestratorGetQueue?: () => Promise<unknown>;
139	    getRunMetadata?: () => Promise<unknown>;
140	    orchestratorStart?: () => Promise<unknown>;
141	  } = {}
142	) {
143	  (globalThis as Record<string, unknown>)['API'] = {
144	    getProject:             apiStubs.getProject             ?? (() => Promise.resolve(makeProject())),
145	    getPlanDocument:        apiStubs.getPlanDocument         ?? (() => Promise.reject({ code: 'NOT_FOUND' })),
146	    getWorkPackageOverview: apiStubs.getWorkPackageOverview  ?? (() => Promise.resolve(null)),
147	    getProjectHealth:       apiStubs.getProjectHealth        ?? (() => Promise.resolve({ work_packages_needing_reset: 0 })),
148	    getRunLogs:             apiStubs.getRunLogs              ?? (() => Promise.resolve([])),
149	    orchestratorGetQueue:   apiStubs.orchestratorGetQueue    ?? (() => Promise.resolve([])),
150	    getRunMetadata:         apiStubs.getRunMetadata          ?? (() => Promise.reject(new Error('not stubbed'))),
151	    orchestratorStart:      apiStubs.orchestratorStart       ?? (() => Promise.reject(new Error('not stubbed'))),
152	  };
153	
154	  globalThis.renderProjectDetail(app, repo, slug);
155	
156	  const start = Date.now();
157	  while (Date.now() - start < 400) {
158	    await new Promise<void>((resolve) => setTimeout(resolve, 15));
159	    const el = app.querySelector('#orchestrator-runs-section');
160	    if (!el || !el.innerHTML.includes('Loading runs')) break;
161	  }
162	  // Extra micro-task flushes for the orchestratorGetQueue promise hop in the
163	  // active-run path (renderProjectDetail → getRunLogs → pollQueue → orchestratorGetQueue
164	  // → renderRunsList).
165	  for (let i = 0; i < 10; i++) await Promise.resolve();
166	}
167	
168	// ---------------------------------------------------------------------------
169	// § 1 — _orchRunsStructureKey (pure function)
170	// ---------------------------------------------------------------------------
171	
172	describe('_orchRunsStructureKey', () => {
173	  it('produces the same key for identical inputs', () => {
174	    const sorted = [
175	      { filename: '20260325T120000-proj.jsonl', is_active: true },
176	      { filename: '20260324T100000-proj.jsonl', is_active: false },
177	    ];
178	    const k1 = globalThis._orchRunsStructureKey(sorted, '20260325T120000-proj.jsonl');
179	    const k2 = globalThis._orchRunsStructureKey(sorted, '20260325T120000-proj.jsonl');
180	    expect(k1).toBe(k2);
181	  });
182	
183	  it('produces different keys when activeFilename changes', () => {
184	    const sorted = [{ filename: '20260325T120000-proj.jsonl', is_active: false }];
185	    const kWithActive  = globalThis._orchRunsStructureKey(sorted, '20260325T120000-proj.jsonl');
186	    const kWithoutActive = globalThis._orchRunsStructureKey(sorted, null);
187	    expect(kWithActive).not.toBe(kWithoutActive);
188	  });
189	
190	  it('produces different keys when the run list changes', () => {
191	    const sorted1 = [{ filename: '20260325T120000-proj.jsonl', is_active: true }];
192	    const sorted2 = [
193	      { filename: '20260326T080000-proj.jsonl', is_active: true },
194	      { filename: '20260325T120000-proj.jsonl', is_active: false },
195	    ];
196	    const k1 = globalThis._orchRunsStructureKey(sorted1, '20260325T120000-proj.jsonl');
197	    const k2 = globalThis._orchRunsStructureKey(sorted2, '20260326T080000-proj.jsonl');
198	    expect(k1).not.toBe(k2);
199	  });
200	
201	  it('treats null and undefined activeFilename as equivalent (no active run)', () => {
202	    const sorted = [{ filename: '20260325T120000-proj.jsonl', is_active: false }];
203	    const kNull      = globalThis._orchRunsStructureKey(sorted, null);
204	    // undefined coerces to null inside the helper
205	    const kUndefined = globalThis._orchRunsStructureKey(sorted, undefined as unknown as null);
206	    expect(kNull).toBe(kUndefined);
207	  });
208	
209	  it('handles an empty sorted array gracefully', () => {
210	    const k1 = globalThis._orchRunsStructureKey([], null);
211	    const k2 = globalThis._orchRunsStructureKey([], null);
212	    expect(k1).toBe(k2);
213	    expect(typeof k1).toBe('string');
214	  });
215	});
216	
217	// ---------------------------------------------------------------------------
218	// § 2 — _patchOrchStatusCard (DOM helper)
219	// ---------------------------------------------------------------------------
220	
221	describe('_patchOrchStatusCard', () => {
222	  let container: HTMLDivElement;
223	
224	  beforeEach(() => {
225	    container = document.createElement('div');
226	    container.id = 'orch-status-card-container';
227	    container.innerHTML = '<div class="orchestrator-status-card">old-card</div>';
228	    document.body.appendChild(container);
229	  });
230	
231	  afterEach(() => {
232	    container.remove();
233	  });
234	
235	  it('is a no-op when the container element is absent', () => {
236	    container.remove(); // detach before the call
237	    // Should not throw
238	    expect(() => globalThis._patchOrchStatusCard({ id: 'q1' })).not.toThrow();
239	  });
240	
241	  it('replaces the container innerHTML with the rendered status card', () => {
242	    globalThis.OrchestratorWidgets.renderStatusCard.mockReturnValue('<div class="orchestrator-status-card">new-card</div>');
243	    globalThis._patchOrchStatusCard({ id: 'q1' });
244	    expect(container.innerHTML).toContain('new-card');
245	    expect(container.innerHTML).not.toContain('old-card');
246	    expect(globalThis.OrchestratorWidgets.renderStatusCard).toHaveBeenCalledWith({ id: 'q1' });
247	  });
248	
249	  it('clears the container innerHTML when matchingQueueEntry is null', () => {
250	    globalThis._patchOrchStatusCard(null);
251	    expect(container.innerHTML).toBe('');
252	  });
253	
254	  it('does not mutate the DOM when the new HTML equals the current innerHTML', () => {
255	    const fixedHtml = '<div class="orchestrator-status-card">same-card</div>';
256	    container.innerHTML = fixedHtml;
257	    globalThis.OrchestratorWidgets.renderStatusCard.mockReturnValue(fixedHtml);
258	
259	    // Spy on innerHTML setter to detect unnecessary writes.
260	    const originalDescriptor = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
261	    const innerHtmlSetter = vi.fn();
262	    Object.defineProperty(container, 'innerHTML', {
263	      get: () => fixedHtml,
264	      set: innerHtmlSetter,
265	      configurable: true,
266	    });
267	
268	    globalThis._patchOrchStatusCard({ id: 'q1' });
269	    expect(innerHtmlSetter).not.toHaveBeenCalled();
270	
271	    // Restore
272	    if (originalDescriptor) {
273	      Object.defineProperty(container, 'innerHTML', originalDescriptor);
274	    }
275	  });
276	});
277	
278	// ---------------------------------------------------------------------------
279	// § 3 — scrollTop save/restore around innerHTML rebuilds
280	// ---------------------------------------------------------------------------
281	
282	describe('renderRunsList scrollTop preservation', () => {
283	  let app: HTMLElement;
284	  let orchContainer: HTMLElement;
285	  let orchSection: HTMLElement;
286	
287	  beforeEach(() => {
288	    // Build a minimal DOM that mirrors what renderProjectDetail creates:
289	    // a scrollable container wrapping the orchestrator runs section.
290	    orchSection = document.createElement('div');
291	    orchSection.id = 'orchestrator-runs-section';
292	
293	    orchContainer = document.createElement('div');
294	    orchContainer.id = 'orchestrator-runs-wrapper';
295	    // Make it behave like a scrollable ancestor in JSDOM
296	    Object.defineProperty(orchContainer, 'scrollTop', {
297	      get: () => orchContainer.dataset['scrollTop'] ? parseInt(orchContainer.dataset['scrollTop']) : 0,
298	      set: (v: number) => { orchContainer.dataset['scrollTop'] = String(v); },
299	      configurable: true,
300	    });
301	    // Mark as scrollable via computedStyle
302	    orchContainer.style.overflowY = 'auto';
303	    orchContainer.appendChild(orchSection);
304	
305	    app = document.createElement('div');
306	    app.appendChild(orchContainer);
307	    document.body.appendChild(app);
308	  });
309	
310	  afterEach(() => {
311	    app.remove();
312	  });
313	
314	  it('restores scrollTop of a scrollable ancestor after a structural rebuild', async () => {
315	    const logs = [
316	      { filename: '20260325T120000-proj.jsonl', is_active: false },
317	      { filename: '20260324T090000-proj.jsonl', is_active: false },
318	    ];
319	
